from fractions import Fraction
import re


_COMPONENT = re.compile(r"([0-9]+(?:\.[0-9]+)?)(ms|w|d|h|m|s)")
_UNIT_ORDER = {"w": 0, "d": 1, "h": 2, "m": 3, "s": 4, "ms": 5}
_UNIT_MILLISECONDS = {
    "w": 7 * 24 * 60 * 60 * 1000,
    "d": 24 * 60 * 60 * 1000,
    "h": 60 * 60 * 1000,
    "m": 60 * 1000,
    "s": 1000,
    "ms": 1,
}


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("duration must be a string")

    value = text.strip()
    if not value:
        raise ValueError("invalid duration")

    negative = value.startswith("-")
    if negative:
        value = value[1:]
    if not value or value.startswith("+"):
        raise ValueError("invalid duration")

    position = 0
    previous_order = -1
    total = Fraction(0)
    saw_fraction = False
    component_count = 0

    while position < len(value):
        match = _COMPONENT.match(value, position)
        if match is None:
            raise ValueError("invalid duration")

        number, unit = match.groups()
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("invalid duration")
        previous_order = order
        component_count += 1

        if "." in number:
            if saw_fraction or match.end() != len(value):
                raise ValueError("invalid duration")
            saw_fraction = True
        total += Fraction(number) * _UNIT_MILLISECONDS[unit]
        position = match.end()

        if position < len(value):
            if value[position] == " ":
                position += 1
                if position == len(value) or value[position] == " ":
                    raise ValueError("invalid duration")

    if component_count == 0:
        raise ValueError("invalid duration")

    numerator, denominator = total.numerator, total.denominator
    milliseconds = (2 * numerator + denominator) // (2 * denominator)
    return -milliseconds if negative else milliseconds
